  stats([['Tài khoản có thể phân bổ',accountAvailable(state)],['Tổng đã dành mục tiêu',reserved(state)]]);b.append(node('p','muted','Nạp tiền vào tài khoản trước. Tiền dành cho mục tiêu vẫn thuộc tài khoản nhưng không thể rút cho đến khi giải phóng. Không cộng trùng tài sản, không tạo thu chi.'));const form=box(),name=field(form,'Tên mục tiêu','Ví dụ: Mua xe máy'),target=field(form,'Số tiền mục tiêu (đ)','22000000');name.maxLength=48;modalButton(form,'Tạo mục tiêu',()=>change(()=>createGoal(state,name.value,amount(target)),'Đã tạo mục tiêu'),'primary');for(const g of f.goals){const form=box();form.append(node('strong','',g.name),node('small','muted',`${money(g.saved)} / ${money(g.target)} · ${g.saved===g.target?'Hoàn thành':Math.floor(g.saved/g.target*100)+'%'}`));const bar=node('div','edu-progress'),fill=node('i');fill.style.width=g.saved/g.target*100+'%';bar.append(fill);form.append(bar);const i=field(form,'Số tiền phân bổ / giải phóng (đ)','100000');const row=node('div','fin-actions');modalButton(row,'Dành thêm',()=>change(()=>changeGoal(state,g.id,amount(i)),'Đã dành tiền'),'primary');modalButton(row,'Giải phóng',()=>change(()=>changeGoal(state,g.id,-amount(i)),'Đã giải phóng tiền'),'secondary');modalButton(row,'Xóa mục tiêu',()=>{if(window.confirm('Xóa mục tiêu và giải phóng phần tiền đã dành?'))change(()=>removeGoal(state,g.id),'Đã xóa mục tiêu')},'secondary');form.append(row);}modalButton(b,'Đến tài khoản',()=>finance('wallet'),'secondary');
